<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('gifts.manage');
if(is_post()){verify_csrf();try{$plain=strtoupper(bin2hex(random_bytes(8)));$ttl=max(1,min(10080,(int)input('ttl_minutes',30)));$pdo=db();$pdo->prepare('INSERT INTO coupons(code_hash,code_reference,title,discount_amount,min_cart_amount,merchant_id,ttl_minutes,expires_at,user_id,created_by) VALUES(?,?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL ? MINUTE),?,?)')->execute([hash('sha256',$plain),transaction_code('CPN'),trim((string)input('title')),trim((string)input('discount_amount')),trim((string)input('min_cart_amount')),((int)input('merchant_id'))?:null,$ttl,$ttl,((int)input('user_id'))?:null,admin()['id']]);$_SESSION['_coupon_once']=$plain;audit_log((int)admin()['id'],'COUPON_CREATED','coupons',(string)$pdo->lastInsertId());flash('success','Coupon created; copy the one-time code shown below.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/rewards/coupons.php');}
$vendors=db()->query('SELECT id,shop_name FROM vendors WHERE status="ACTIVE" ORDER BY shop_name')->fetchAll();$rows=db()->query('SELECT c.*,v.shop_name FROM coupons c LEFT JOIN vendors v ON v.id=c.merchant_id ORDER BY c.id DESC LIMIT 200')->fetchAll();$once=$_SESSION['_coupon_once']??null;unset($_SESSION['_coupon_once']);$pageTitle='Coupons & minimum cart';require APP_ROOT.'/includes/header.php';?>
<?php if($once):?><section class="panel one-time"><h2>One-time coupon code</h2><input readonly value="<?=e($once)?>"></section><?php endif?><section class="panel"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Discount amount</label><input name="discount_amount" pattern="\d+(\.\d{1,2})?" required></div><div class="field"><label>Minimum cart amount</label><input name="min_cart_amount" value="300.00" required></div><div class="field"><label>TTL minutes</label><input name="ttl_minutes" type="number" min="1" max="10080" value="30" required></div><div class="field"><label>Merchant restriction</label><select name="merchant_id"><option value="">Any merchant</option><?php foreach($vendors as $v):?><option value="<?=e($v['id'])?>"><?=e($v['shop_name'])?></option><?php endforeach?></select></div><div class="field"><label>User ID (optional)</label><input name="user_id" type="number" min="1"></div><div class="field full"><button class="btn">Generate coupon</button></div></form></section><section class="panel"><h2>Coupon audit</h2><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Discount</th><th>Minimum cart</th><th>Merchant</th><th>Status</th><th>Expires</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['code_reference'])?></td><td><?=money($r['discount_amount'])?></td><td><?=money($r['min_cart_amount'])?></td><td><?=e($r['shop_name']??'Any')?></td><td><?=e($r['status'])?></td><td><?=e($r['expires_at']??'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
